import{z as i,x as d,o as A,c as C,q as t,j as l,D as E,d as n,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"填充预言机","description":"","frontmatter":{"title":"填充预言机","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/padding-oracle.md","filePath":"cs/padding-oracle.md","lastUpdated":1791413859000}'),B={name:"cs/padding-oracle.md"};function p(c,a,D,h,m,u){const r=d("Mermaid");return A(),C("div",null,[a[2]||(a[2]=t('<h1 id="填充预言机" tabindex="-1">填充预言机 <a class="header-anchor" href="#填充预言机" aria-label="Permalink to &quot;填充预言机&quot;">​</a></h1><div class="epigraph"><p>CBC 解密后若把「填充合不合法」与「MAC 失败」用可区分的方式告诉外界，主动敌手就能把解密器当成一位一位的预言。防御是 AEAD，以及失败不可区分。</p><footer>—— Vaudenay, Security Flaws Induced by CBC Padding, EUROCRYPT 2002；对照 TLS 对填充与 MAC 的历史修补</footer></div><p>上一课<a href="/cs/nonce-misuse">nonce 误用</a>是状态合同。缺口是<strong>错误通道</strong>：即使 nonce 唯一，分组密码的填充校验若变成可观测谓词，Dolev–Yao 的理想锁也不成立。本课讲机制与防御，不给可复现的明文恢复步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PKCS#7 一类填充让明文长度凑整。CBC 解密后检查填充。若攻击者改密文块并得知「填充错还是 MAC 错」，就得到一位预言。历史 TLS 与若干框架因此换套件。缺口是：完整性必须在解密前或与解密原子地验；错误不可区分。</p><h3 id="不是作业题" tabindex="-1">不是作业题 <a class="header-anchor" href="#不是作业题" aria-label="Permalink to &quot;不是作业题&quot;">​</a></h3><p>课程禁止把预言机利用写成实验指导。需要的只是：可区分的失败 = 额外的解密预言；关掉它。</p><p><span class="marginnote">Vaudenay 2002。Lucky Thirteen 一类是计时变体，同属错误/时间通道。TLS 1.3 删除 CBC 套件，从根上换 AEAD。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述 Encrypt-then-MAC 与 AEAD 如何让「密文未认证则不解密」。统一错误码与常数时间失败路径。旧栈若必须留 CBC，也不可把填充错误单独抛出。</p>',11)),(A(),l(s,null,{default:E(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CT%5B%22%E6%94%B9%E8%BF%87%E7%9A%84%E5%AF%86%E6%96%87%22%5D%20--%3E%20DEC%5B%22%E8%A7%A3%E5%AF%86%E5%B9%B6%E6%9F%A5%E5%A1%AB%E5%85%85%22%5D%0A%20%20DEC%20--%3E%20E1%5B%22%E5%A1%AB%E5%85%85%E9%94%99%22%5D%0A%20%20DEC%20--%3E%20E2%5B%22MAC%20%E9%94%99%22%5D%0A%20%20E1%20--%3E%20ORACLE%5B%22%E5%8F%AF%E5%8C%BA%E5%88%86%E5%88%99%E6%88%90%E9%A2%84%E8%A8%80%22%5D%0A%20%20E2%20--%3E%20ORACLE%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"主动敌手的能力包括改字节并看反应。规格若把内部校验暴露成不同 HTTP 状态、不同耗时、不同日志，就等于提供 $ \\mathrm{Dec} $ 的部分信息。这与 nonce 复用正交：即使每条消息 nonce 都新，错误通道仍在。",-1)),a[5]||(a[5]=e("p",null,"同样是「验证失败」，新旧栈的路径差在哪一步：旧栈把解密、查填充、验 MAC 三件事分开报告，每次失败都泄露一层内部状态；AEAD 把认证挪到解密之前，失败只有一句话。",-1)),(A(),l(s,null,{default:E(()=>[o(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CT%5B%22%E6%94%B6%E5%88%B0%E8%A2%AB%E7%AF%A1%E6%94%B9%E7%9A%84%E5%AF%86%E6%96%87%22%5D%20--%3E%20NEW%5B%22AEAD%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20CT%20--%3E%20OLD%5B%22%E6%97%A7%20CBC%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20NEW%20--%3E%20AUTH%7B%22%E5%85%88%E9%AA%8C%E8%AE%A4%E8%AF%81%E6%A0%87%E7%AD%BE%22%7D%0A%20%20AUTH%20--%3E%7C%22%E4%B8%8D%E5%8C%B9%E9%85%8D%22%7C%20ONE%5B%22%E5%94%AF%E4%B8%80%E9%94%99%E8%AF%AF%E7%A0%81%EF%BC%8C%E5%B8%B8%E6%95%B0%E6%97%B6%E9%97%B4%E8%BF%94%E5%9B%9E%22%5D%0A%20%20AUTH%20--%3E%7C%22%E5%8C%B9%E9%85%8D%22%7C%20DEC%5B%22%E5%86%8D%E8%A7%A3%E5%AF%86%EF%BC%8C%E8%BE%93%E5%87%BA%E6%98%8E%E6%96%87%22%5D%0A%20%20OLD%20--%3E%20D1%5B%22%E8%A7%A3%E5%AF%86%20%E2%86%92%20%E6%9F%A5%E5%A1%AB%E5%85%85%20%E2%86%92%20%E9%AA%8C%20MAC%EF%BC%8C%E5%88%86%E5%BC%80%E6%8A%A5%E9%94%99%22%5D%0A%20%20D1%20--%3E%20ORC%5B%22%E5%A4%B1%E8%B4%A5%E5%8F%AF%E5%8C%BA%E5%88%86%20%3D%20%E9%A2%84%E8%A8%80%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">术语翻译：预言机就是「对特定问题有问必答的黑盒」——服务器通过报错差异回答「填充对不对」；攻击者不破密码，只是把这个通道一遍遍问到底，把答案拼成明文。</span></p><p><span class="marginnote">直觉类比：像把保险柜搬回家慢慢试——柜子在机房时本不可攻，但服务器每转一次就暗示「差一点还是差很多」，等于把刻度盘反馈带走了；AEAD 就是让柜子只会说「开」或「不开」两句话。</span></p><p><span class="marginnote">常见误区：初学者容易以为「加密了就万事大吉」。CBC 只管机密性时，填充与 MAC 的失败若被区别对待，机密也会从错误通道漏掉——机密与完整必须绑在一起验（AEAD），不能各管各的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分析某 CVE 的报文。哈希结构下一课：消息摘要如何迭代，与填充预言无关，但同属「把可变长输入收成固定对象」的进阶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>nonce 合同之外，错误信息也是通道。</li><li>CBC 填充校验可被当成预言；不要区分失败原因。</li><li>AEAD 与 Encrypt-then-MAC 从结构上关掉。</li><li>下一课 Merkle–Damgård：哈希的迭代结构。</li><li>出处：Vaudenay, 2002；Krawczyk 对 MAC-then-encrypt 的讨论；RFC 8446 删除 CBC。</li></ul>',7))])}const f=i(B,[["render",p]]);export{F as __pageData,f as default};
